sections.code:
package main

import (
    "bufio"
    "fmt"
    "os"
)

func main() {
    in := bufio.NewReader(os.Stdin)
    out := bufio.NewWriter(os.Stdout)
    defer out.Flush()
    var n, k int
    if _, err := fmt.Fscan(in, &n, &k); err != nil { return }
    a := []int{}
    for {
        var value int
        if _, err := fmt.Fscan(in, &value); err != nil { break }
        a = append(a, value)
    }
    _ = k
    prefix := make([]int, n + 1);
    for fill := range prefix { prefix[fill] = 0; }
    for i := 0; i < n; i++ {
        prefix[i + 1] = prefix[i] + a[i];
    }
    for q := 0; q < k; q++ {
        left := a[n + 2 * q];
        right := a[n + 2 * q + 1];
        fmt.Fprintln(out, prefix[right] - prefix[left]);
    }
}

